   phaseRef.current='preparing';setPhase('正在准备收音');const needsWakeNow=()=>requiresWakeCheck({handsfree:handsfreeRef.current,conversationActive:conversationActive.current,wakeUntil:wakeUntil.current});let needsWake=needsWakeNow();
